+import { useEffect, useState } from 'react';
+import { detalharAtividade } from '../api';
+
+const DetalheAtividade = ({ id }) => {
+  const [atividade, setAtividade] = useState(null);
+
+  useEffect(() => {
+    detalharAtividade(id).then(setAtividade);
+  }, [id]);
+
+  if (!atividade) return <div>Carregando...</div>;
+
+  return (
+    <div>
