+      <p>Vagas: {atividade.vagas}</p>
+      <ul>
+        {atividade.encontros.map(enc => (
+          <li key={enc.id}>{enc.inicio} - {enc.fim}</li>
+        ))}
+      </ul>
+    </div>
+  );
+};
+
+export default DetalheAtividade;

