import { useEffect, useState } from 'react';
import { listarAtividades } from '../api';

const GradeAtividades = ({ onSelectAtividade }) => {
  const [atividades, setAtividades] = useState([]);
  const [dia, setDia] = useState('');
  const [tipo, setTipo] = useState('');
  const [erro, setErro] = useState(null);

  const diasDisponiveis = [
    { label: 'Todos', value: '' },
    { label: 'Seg 19/10', value: '2026-10-19' },
    { label: 'Ter 20/10', value: '2026-10-20' },
    { label: 'Qua 21/10', value: '2026-10-21' },
    { label: 'Qui 22/10', value: '2026-10-22' },
    { label: 'Sex 23/10', value: '2026-10-23' },
  ];

  const carregarAtividades = async () => {
    try {
      setErro(null);
      const data = await listarAtividades(dia || null, tipo || null);
      setAtividades(data);
    } catch (err) {
      setErro(err.message);
    }
  };

  useEffect(() => {
    carregarAtividades();
  }, [dia, tipo]);

  return (
    <div style={{ padding: '16px', border: '1px solid var(--border)', borderRadius: '8px', textAlign: 'left' }}>
      <h2>Programação de Atividades</h2>
      {erro && <div style={{ color: 'red', marginBottom: '10px' }}>{erro}</div>}

      <div style={{ display: 'flex', gap: '16px', marginBottom: '16px', flexWrap: 'wrap' }}>
        <div>
          <label style={{ marginRight: '8px', fontWeight: 'bold' }}>Dia:</label>
          <select value={dia} onChange={(e) => setDia(e.target.value)} data-testid="select-dia">
            {diasDisponiveis.map((d) => (
              <option key={d.value} value={d.value}>
                {d.label}
              </option>
            ))}
          </select>
        </div>

        <div>
          <label style={{ marginRight: '8px', fontWeight: 'bold' }}>Tipo:</label>
          <select value={tipo} onChange={(e) => setTipo(e.target.value)} data-testid="select-tipo">
            <option value="">Todos</option>
            <option value="palestra">Palestra</option>
            <option value="minicurso">Minicurso</option>
          </select>
        </div>
      </div>

      <div style={{ display: 'grid', gap: '12px' }}>
        {atividades.length === 0 ? (
          <p>Nenhuma atividade encontrada.</p>
        ) : (
          atividades.map((atv) => (
            <div
              key={atv.id}
              onClick={() => onSelectAtividade(atv.id)}
              style={{
                padding: '12px',
                border: '1px solid var(--border)',
                borderRadius: '6px',
                cursor: 'pointer',
                background: 'var(--social-bg)',
                transition: 'box-shadow 0.2s',
              }}
              className="atividade-item"
              data-testid={`atividade-${atv.id}`}
            >
              <h3 style={{ margin: '0 0 6px 0', color: 'var(--text-h)' }}>{atv.titulo}</h3>
              <div style={{ fontSize: '14px', display: 'flex', gap: '12px' }}>
                <span style={{ textTransform: 'capitalize', fontWeight: 'bold' }}>{atv.tipo}</span>
                <span>Sala: {atv.salaId}</span>
                <span>Vagas Restantes: {atv.vagasRestantes}</span>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default GradeAtividades;

import { useEffect, useState } from 'react';
import { detalharAtividade } from '../api';

const DetalheAtividade = ({ atividadeId, onBack }) => {
  const [atividade, setAtividade] = useState(null);
  const [erro, setErro] = useState(null);

  const carregarAtividade = async () => {
    if (!atividadeId) return;
    try {
      setErro(null);
      const data = await detalharAtividade(atividadeId);
      setAtividade(data);
    } catch (err) {
      setErro(err.message);
    }
  };

  useEffect(() => {
    carregarAtividade();
  }, [atividadeId]);

  if (!atividadeId) {
    return (
      <div style={{ padding: '16px', border: '1px solid var(--border)', borderRadius: '8px', textAlign: 'center' }}>
        <p>Selecione uma atividade para visualizar os detalhes.</p>
      </div>
    );
  }

  if (erro) {
    return (
      <div style={{ padding: '16px', border: '1px solid var(--border)', borderRadius: '8px', textAlign: 'left' }}>
        <button onClick={onBack} style={{ marginBottom: '12px' }}>Voltar</button>
        <div style={{ color: 'red' }}>{erro}</div>
      </div>
    );
  }

  if (!atividade) {
    return (
      <div style={{ padding: '16px', border: '1px solid var(--border)', borderRadius: '8px', textAlign: 'center' }}>
        <p>Carregando detalhes...</p>
      </div>
    );
  }

  const formatarData = (isoStr) => {
    try {
      const date = new Date(isoStr);
      return date.toLocaleString('pt-BR', {
        day: '2-digit',
        month: '2-digit',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
      });
    } catch (e) {
      return isoStr;
    }
  };

  return (
    <div style={{ padding: '16px', border: '1px solid var(--border)', borderRadius: '8px', textAlign: 'left' }}>
      {onBack && (
        <button onClick={onBack} style={{ marginBottom: '12px', padding: '6px 12px', cursor: 'pointer' }}>
          Voltar para a lista
        </button>
      )}
      <h2 style={{ margin: '0 0 12px 0', color: 'var(--text-h)' }}>{atividade.titulo}</h2>

      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '16px', marginBottom: '20px' }}>
        <div>
          <strong style={{ display: 'block', fontSize: '14px', color: 'var(--text)' }}>TIPO</strong>
          <span style={{ fontSize: '16px', textTransform: 'capitalize', fontWeight: 'bold' }}>{atividade.tipo}</span>
        </div>
        <div>
          <strong style={{ display: 'block', fontSize: '14px', color: 'var(--text)' }}>SALA</strong>
          <span style={{ fontSize: '16px', fontWeight: 'bold' }}>{atividade.salaId}</span>
        </div>
        <div>
          <strong style={{ display: 'block', fontSize: '14px', color: 'var(--text)' }}>SITUAÇÃO</strong>
          <span style={{ fontSize: '16px', textTransform: 'capitalize', fontWeight: 'bold' }}>{atividade.situacao}</span>
        </div>
        <div>
          <strong style={{ display: 'block', fontSize: '14px', color: 'var(--text)' }}>CARGA HORÁRIA</strong>
          <span style={{ fontSize: '16px' }}>{atividade.cargaHorariaMinutos} minutos</span>
        </div>
      </div>

      <div style={{ borderTop: '1px solid var(--border)', paddingTop: '16px', marginBottom: '20px' }}>
        <h3 style={{ margin: '0 0 12px 0' }}>Vagas e Inscrições</h3>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(120px, 1fr))', gap: '12px' }}>
          <div style={{ padding: '8px', background: 'var(--code-bg)', borderRadius: '4px', textAlign: 'center' }}>
            <span style={{ fontSize: '20px', fontWeight: 'bold', display: 'block' }}>{atividade.vagas}</span>
            <span style={{ fontSize: '12px' }}>Vagas Totais</span>
          </div>
          <div style={{ padding: '8px', background: 'var(--code-bg)', borderRadius: '4px', textAlign: 'center' }}>
            <span style={{ fontSize: '20px', fontWeight: 'bold', display: 'block' }}>{atividade.ocupadas}</span>
            <span style={{ fontSize: '12px' }}>Ocupadas</span>
          </div>
          <div style={{ padding: '8px', background: 'var(--code-bg)', borderRadius: '4px', textAlign: 'center' }}>
            <span style={{ fontSize: '20px', fontWeight: 'bold', display: 'block' }}>{atividade.vagasRestantes}</span>
            <span style={{ fontSize: '12px' }}>Restantes</span>
          </div>
          <div style={{ padding: '8px', background: 'var(--code-bg)', borderRadius: '4px', textAlign: 'center' }}>
            <span style={{ fontSize: '20px', fontWeight: 'bold', display: 'block' }}>{atividade.emEspera}</span>
            <span style={{ fontSize: '12px' }}>Em Espera</span>
          </div>
        </div>
      </div>

      <div style={{ borderTop: '1px solid var(--border)', paddingTop: '16px' }}>
        <h3 style={{ margin: '0 0 12px 0' }}>Encontros</h3>
        {atividade.encontros && atividade.encontros.length > 0 ? (
          <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
            {atividade.encontros.map((enc, idx) => (
              <li
                key={enc.id || idx}
                style={{
                  padding: '10px',
                  borderBottom: idx === atividade.encontros.length - 1 ? 'none' : '1px solid var(--border)',
                  display: 'flex',
                  justifyContent: 'space-between',
                }}
              >
                <span>Encontro #{idx + 1}</span>
                <span style={{ fontWeight: 'bold' }}>
                  {formatarData(enc.inicio)} até {formatarData(enc.fim)}
                </span>
              </li>
            ))}
          </ul>
        ) : (
          <p>Nenhum encontro programado.</p>
        )}
      </div>
    </div>
  );
};

export default DetalheAtividade;

import { useEffect, useState } from 'react';
import { criarAtividade, listarSalas } from '../api';

const CriarAtividade = ({ onSuccess }) => {
  const [salas, setSalas] = useState([]);
  const [titulo, setTitulo] = useState('');
  const [tipo, setTipo] = useState('palestra');
  const [salaId, setSalaId] = useState('');
  const [vagas, setVagas] = useState(20);
  const [encontros, setEncontros] = useState([]);
  const [erro, setErro] = useState(null);
  const [loading, setLoading] = useState(false);

  // For adding a new meeting
  const [novoInicio, setNovoInicio] = useState('');
  const [novoFim, setNovoFim] = useState('');

  useEffect(() => {
    listarSalas()
      .then((data) => {
        setSalas(data);
        if (data.length > 0) {
          setSalaId(data[0].id);
        }
      })
      .catch((err) => {
        // Falls back to standard rooms in contract if API fails
        setSalas([
          { id: 'auditorio', nome: 'Auditório Central', capacidade: 200 },
          { id: 'sala-101', nome: 'Sala 101', capacidade: 40 },
          { id: 'sala-102', nome: 'Sala 102', capacidade: 40 },
          { id: 'lab-3', nome: 'Laboratório 3', capacidade: 20 },
        ]);
        setSalaId('auditorio');
      });
  }, []);

  const handleAdicionarEncontro = (e) => {
    e.preventDefault();
    if (!novoInicio || !novoFim) {
      alert('Por favor, preencha o início e fim do encontro.');
      return;
    }

    // Format datetime-local format 'YYYY-MM-DDTHH:MM' into ISO with -03:00 offset
    const inicioFormatted = `${novoInicio}:00-03:00`;
    const fimFormatted = `${novoFim}:00-03:00`;

    setEncontros([...encontros, { inicio: inicioFormatted, fim: fimFormatted }]);
    setNovoInicio('');
    setNovoFim('');
  };

  const handleRemoverEncontro = (index) => {
    setEncontros(encontros.filter((_, i) => i !== index));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setErro(null);
    setLoading(true);

    const dadosAtividade = {
      titulo,
      tipo,
      salaId,
      vagas: parseInt(vagas, 10),
      encontros,
    };

    try {
      const novaAtv = await criarAtividade(dadosAtividade);
      alert('Atividade criada com sucesso!');
      // Reset form
      setTitulo('');
      setTipo('palestra');
      setVagas(20);
      setEncontros([]);
      if (onSuccess) onSuccess(novaAtv);
    } catch (err) {
      // Rule 4: Do not invent/rewrite error messages; render the exact message returned by the API
      setErro(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ padding: '16px', border: '1px solid var(--border)', borderRadius: '8px', textAlign: 'left' }}>
      <h2>Criar Nova Atividade</h2>

      {erro && (
        <div style={{ padding: '12px', background: 'rgba(255, 0, 0, 0.1)', color: 'red', border: '1px solid red', borderRadius: '4px', marginBottom: '16px' }} data-testid="error-message">
          {erro}
        </div>
      )}

      <form onSubmit={handleSubmit} style={{ display: 'grid', gap: '16px' }}>
        <div>
          <label style={{ display: 'block', fontWeight: 'bold', marginBottom: '4px' }}>Título</label>
          <input
            type="text"
            value={titulo}
            onChange={(e) => setTitulo(e.target.value)}
            style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
            required
            data-testid="input-titulo"
          />
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px' }}>
          <div>
            <label style={{ display: 'block', fontWeight: 'bold', marginBottom: '4px' }}>Tipo</label>
            <select value={tipo} onChange={(e) => setTipo(e.target.value)} style={{ width: '100%', padding: '8px' }} data-testid="select-tipo-form">
              <option value="palestra">Palestra</option>
              <option value="minicurso">Minicurso</option>
            </select>
          </div>

          <div>
            <label style={{ display: 'block', fontWeight: 'bold', marginBottom: '4px' }}>Sala</label>
            <select value={salaId} onChange={(e) => setSalaId(e.target.value)} style={{ width: '100%', padding: '8px' }} data-testid="select-sala">
              {salas.map((s) => (
                <option key={s.id} value={s.id}>
                  {s.nome} (Capacidade: {s.capacidade})
                </option>
              ))}
            </select>
          </div>
        </div>

        <div>
          <label style={{ display: 'block', fontWeight: 'bold', marginBottom: '4px' }}>Vagas</label>
          <input
            type="number"
            value={vagas}
            onChange={(e) => setVagas(e.target.value)}
            style={{ width: '100%', padding: '8px', boxSizing: 'border-box' }}
            min="1"
            required
            data-testid="input-vagas"
          />
        </div>

        <div style={{ border: '1px solid var(--border)', padding: '12px', borderRadius: '6px' }}>
          <h3 style={{ margin: '0 0 12px 0' }}>Encontros</h3>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr auto', gap: '8px', alignItems: 'end', marginBottom: '12px' }}>
            <div>
              <label style={{ display: 'block', fontSize: '12px', fontWeight: 'bold' }}>Início</label>
              <input
                type="datetime-local"
                value={novoInicio}
                onChange={(e) => setNovoInicio(e.target.value)}
                style={{ width: '100%', padding: '6px' }}
                data-testid="input-encontro-inicio"
              />
            </div>
            <div>
              <label style={{ display: 'block', fontSize: '12px', fontWeight: 'bold' }}>Fim</label>
              <input
                type="datetime-local"
                value={novoFim}
                onChange={(e) => setNovoFim(e.target.value)}
                style={{ width: '100%', padding: '6px' }}
                data-testid="input-encontro-fim"
              />
            </div>
            <button type="button" onClick={handleAdicionarEncontro} style={{ padding: '6px 12px' }} data-testid="btn-add-encontro">
              +
            </button>
          </div>

          {encontros.length > 0 ? (
            <ul style={{ listStyle: 'none', padding: 0, margin: 0 }}>
              {encontros.map((enc, idx) => (
                <li
                  key={idx}
                  style={{
                    display: 'flex',
                    justifyContent: 'space-between',
                    alignItems: 'center',
                    padding: '6px 0',
                    borderBottom: idx === encontros.length - 1 ? 'none' : '1px solid var(--border)',
                  }}
                >
                  <span style={{ fontSize: '14px' }}>
                    #{idx + 1}: {enc.inicio.substring(0, 16).replace('T', ' ')} até {enc.fim.substring(11, 16)}
                  </span>
                  <button
                    type="button"
                    onClick={() => handleRemoverEncontro(idx)}
                    style={{ background: '#ff4d4d', color: '#fff', border: 'none', borderRadius: '4px', padding: '2px 6px', cursor: 'pointer' }}
                  >
                    Remover
                  </button>
                </li>
              ))}
            </ul>
          ) : (
            <p style={{ margin: 0, fontSize: '14px', color: 'var(--text)' }}>Nenhum encontro adicionado ainda.</p>
          )}
        </div>

        <button
          type="submit"
          disabled={loading}
          style={{
            background: 'var(--accent)',
            color: '#fff',
            border: 'none',
            padding: '12px',
            borderRadius: '6px',
            fontSize: '16px',
            fontWeight: 'bold',
            cursor: 'pointer',
          }}
        >
          {loading ? 'Criando...' : 'Salvar Atividade'}
        </button>
      </form>
    </div>
  );
};

export default CriarAtividade;

import { useState, useEffect } from 'react';
import './App.css';
import { setUsuario } from './api';
import GradeAtividades from './pages/GradeAtividades';
import DetalheAtividade from './pages/DetalheAtividade';
import CriarAtividade from './pages/CriarAtividade';

const usuarios = [
  { id: 'org-ana', nome: 'Ana Beatriz Lima', papel: 'organizacao' },
  { id: 'org-bruno', nome: 'Bruno Tavares', papel: 'organizacao' },
  { id: 'p-carla', nome: 'Carla Mendes Souza', papel: 'participante' },
  { id: 'p-diego', nome: 'Diego Alves', papel: 'participante' },
  { id: 'p-elisa', nome: 'Elisa Fernandes da Rocha', papel: 'participante' },
  { id: 'p-fabio', nome: 'Fábio Nogueira', papel: 'participante' },
  { id: 'p-gabriela', nome: 'Gabriela Moura Castro', papel: 'participante' },
  { id: 'p-heitor', nome: 'Heitor Campos', papel: 'participante' },
  { id: 'p-isadora', nome: 'Isadora Ribeiro dos Santos', papel: 'participante' },
  { id: 'p-joao', nome: 'João Pedro Martins', papel: 'participante' },
];

function App() {
  const [usuarioAtivo, setUsuarioAtivo] = useState(usuarios[0].id);
  const [pagina, setPagina] = useState('grade'); // 'grade' | 'criar'
  const [atividadeSelecionadaId, setAtividadeSelecionadaId] = useState(null);

  // Update backend header whenever selected user changes
  useEffect(() => {
    setUsuario(usuarioAtivo);
  }, [usuarioAtivo]);

  const usuarioObjeto = usuarios.find((u) => u.id === usuarioAtivo);

  const handleSelectAtividade = (id) => {
    setAtividadeSelecionadaId(id);
  };

  const handleCriacaoSucesso = () => {
    setPagina('grade');
  };

  return (
    <div style={{ padding: '24px', maxWidth: '1200px', margin: '0 auto', boxSizing: 'border-box' }}>
      <header
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          alignItems: 'center',
          borderBottom: '1px solid var(--border)',
          paddingBottom: '16px',
          marginBottom: '24px',
          flexWrap: 'wrap',
          gap: '16px',
        }}
      >
        <div style={{ textAlign: 'left' }}>
          <h1 style={{ margin: '0 0 4px 0', fontSize: '28px', letterSpacing: '-0.5px' }}>Semana Acadêmica</h1>
          <p style={{ margin: 0, fontSize: '14px', color: 'var(--text)' }}>Módulo M1 - Grade de Atividades</p>
        </div>

        <div style={{ display: 'flex', alignItems: 'center', gap: '16px' }}>
          <div style={{ textAlign: 'right' }}>
            <label style={{ display: 'block', fontSize: '12px', fontWeight: 'bold', color: 'var(--text)' }}>
              Simular Usuário:
            </label>
            <select
              value={usuarioAtivo}
              onChange={(e) => setUsuarioAtivo(e.target.value)}
              style={{ padding: '6px 12px', borderRadius: '4px', border: '1px solid var(--border)' }}
              data-testid="select-usuario"
            >
              {usuarios.map((u) => (
                <option key={u.id} value={u.id}>
                  {u.nome} ({u.papel === 'organizacao' ? 'Org' : 'Part'})
                </option>
              ))}
            </select>
          </div>
          <div
            style={{
              padding: '6px 12px',
              borderRadius: '4px',
              background: usuarioObjeto?.papel === 'organizacao' ? 'rgba(170, 59, 255, 0.15)' : 'var(--code-bg)',
              border: '1px solid var(--border)',
              fontSize: '12px',
              fontWeight: 'bold',
            }}
          >
            {usuarioObjeto?.papel === 'organizacao' ? 'PAINEL ORGANIZAÇÃO' : 'VISUALIZAÇÃO PARTICIPANTE'}
          </div>
        </div>
      </header>

      <nav style={{ display: 'flex', gap: '12px', marginBottom: '24px' }}>
        <button
          onClick={() => {
            setPagina('grade');
            setAtividadeSelecionadaId(null);
          }}
          style={{
            padding: '10px 20px',
            borderRadius: '6px',
            border: 'none',
            background: pagina === 'grade' ? 'var(--accent)' : 'var(--code-bg)',
            color: pagina === 'grade' ? '#fff' : 'var(--text)',
            fontWeight: 'bold',
            cursor: 'pointer',
          }}
          data-testid="nav-grade"
        >
          Programação
        </button>

        {/* Render for both to allow verification of organization only actions by API */}
        <button
          onClick={() => setPagina('criar')}
          style={{
            padding: '10px 20px',
            borderRadius: '6px',
            border: 'none',
            background: pagina === 'criar' ? 'var(--accent)' : 'var(--code-bg)',
            color: pagina === 'criar' ? '#fff' : 'var(--text)',
            fontWeight: 'bold',
            cursor: 'pointer',
          }}
          data-testid="nav-criar"
        >
          Criar Atividade
        </button>
      </nav>

      <main style={{ minHeight: '400px' }}>
        {pagina === 'grade' ? (
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '24px', alignItems: 'start' }}>
            <GradeAtividades onSelectAtividade={handleSelectAtividade} />
            <DetalheAtividade
              atividadeId={atividadeSelecionadaId}
              onBack={() => setAtividadeSelecionadaId(null)}
            />
          </div>
        ) : (
          <CriarAtividade onSuccess={handleCriacaoSucesso} />
        )}
      </main>
    </div>
  );
}

